    "subject": "Mikrobiyoloji",
    "professor": "Belirtilmemiş",
    "question": "Aşağıdaki antibiyotiklerden hangisi bakterisid etkili olmayıp bakteriyostatik etki gösterir?",
    "options": [
      {
        "letter": "A",
        "text": "Gentamisin"
      },
      {
        "letter": "B",
        "text": "Siprofloksasin"
      },
      {
        "letter": "C",
        "text": "Vankomisin"
      },
      {
        "letter": "D",
        "text": "Penisilin G"
      },
      {
        "letter": "E",
        "text": "Tetrasiklin"
      }
    ],
    "answer": "E",
    "open_answer": "",
    "explanation": "**Tetrasiklin**, bakteri ribozomunun 30S alt birimine reversibl bağlanıp aminoaçil-tRNA'nın A bölgesine girişini bloke ederek protein sentezini durdurur ve **bakteriyostatik** etki yapar. Gentamisin, seftriakson, vankomisin ve florokinolonlar ise **bakterisid** etkilidir.",
    "note": "Hatırlanan çıkmış soru kökünden 5 şıklı çoktan seçmeli soruya tamamlanmıştır.",
    "q_type": "mcq",
    "incomplete": false,
