    "q_num": 5,
    "subject": "Mikrobiyoloji",
    "professor": "Belirtilmemiş",
    "question": "Rutin idrar kültüründe anlamlı bakteri üremesi sonucu en erken ne zaman değerlendirilebilir?",
    "options": [
      {
        "letter": "A",
        "text": "6-8 saat"
      },
      {
        "letter": "B",
        "text": "2-4 saat"
      },
      {
        "letter": "C",
        "text": "48-72 saat"
      },
      {
        "letter": "D",
        "text": "18-24 saat"
      },
      {
        "letter": "E",
        "text": "1 hafta"
      }
    ],
    "answer": "D",
    "open_answer": "",
    "explanation": "İdrar yolu enfeksiyonu şüphesinde yapılan rutin idrar kültürlerinde, ekim yapılan kanlı ve EMB agarlar 35–37 °C'de standart olarak **18–24 saat** inkübe edilir ve bu sürenin sonunda koloni sayımı ile üreyen bakterinin morfolojisi en erken güvenilir şekilde değerlendirilir.",
    "note": "Hatırlanan çıkmış soru kökünden 5 şıklı çoktan seçmeli soruya tamamlanmıştır.",
    "q_type": "mcq",
    "incomplete": false,
