    "explanation": "Bakteri hücrelerinin düzenli ikili bölünmeyle geometrik olarak en hızlı çoğaldığı ve metabolik olarak en aktif olduğu dönem **logaritmik (eksponansiyel) fazdır**. Hücre duvarı sentezi bu evrede maksimum olduğundan, beta-laktam gibi bakterisid antibiyotiklerin öldürücü etkisine en duyarlı evredir.",
    "note": "Hatırlanan çıkmış soru kökünden 5 şıklı çoktan seçmeli soruya tamamlanmıştır.",
