    "professor": "Belirtilmemiş",
    "question": "Bakteri hücre duvarı peptidoglikan sentezinde çapraz bağların (transpeptidasyon) kurulmasından sorumlu olan ve beta-laktam antibiyotiklerin bağlandığı enzim hangisidir?",
