    "professor": "Belirtilmemiş",
    "question": "Aşağıdakilerden hangisi nükleozom yapısının değişmesine ihtiyaç duyulan nedenlerden biri değildir ?",
    "options": [
      {
        "letter": "A",
        "text": "Gen ekspresyonu"
      },
      {
        "letter": "B",
        "text": "DNA replikasyonu"
      },
      {
        "letter": "C",
        "text": "Programlanmış hücre ölümü"
      },
      {
        "letter": "D",
        "text": "DNA tamiri"
      },
      {
        "letter": "E",
        "text": "Kromozom segregasyonu"
      }
    ],
    "answer": "C",
    "open_answer": "",
    "explanation": "Gen ekspresyonu, DNA replikasyonu ve tamiri sırasında DNA'ya proteinlerin erişebilmesi için nükleozomların yeniden modellenmesi şarttır; ancak **programlanmış hücre ölümünde (apoptoz)** kromatin kaspaz bağımlı endonükleazlarca internükleozomal kesilerek geri dönüşsüz yıkılır.",
    "note": "Cevap anahtarı tıbbi literatüre göre tamamlanmıştır.",
