    "professor": "Belirtilmemiş",
    "question": "İnterfaz kromatininin organizasyonu hakkında aşağıda verilenlerden hangisi yanlıştır?",
    "options": [
      {
        "letter": "A",
        "text": "İnterfaz nükleusundaki kromatin ilmekler şeklinde organize olmuştur."
      },
      {
        "letter": "B",
        "text": "İnterfazda kromatinin çoğu yoğun olmayan durumdadır ve ökromatin adı verilir."
      },
      {
        "letter": "C",
        "text": "İnterfazda aktif gen transkripsiyonu gerçekleşir."
      },
      {
        "letter": "D",
        "text": "İnterfaz kromatininin yaklaşık %10'u heterokromatin yapıdadır."
      },
      {
        "letter": "E",
        "text": "İnterfazda kromatin en yoğun katlanma şekli olan kromozom halini alır."
      }
    ],
    "answer": "E",
    "open_answer": "",
    "explanation": "Kromatinin en yüksek düzeyde yoğunlaşarak mikroskopta belirgin çift kromatitli kromozom morfolojisine ulaştığı evre interfaz değil, mitozun **metafaz** evresidir. İnterfaz evresinde gen transkripsiyonu ve replikasyonun gerçekleşebilmesi için kromatin çoğunlukla gevşek (ökromatin) haldedir.",
    "note": "Hatırlanan 3 şıklı sorudan 5 şıklı çoktan seçmeli soruya tamamlanmıştır.",
