    "professor": "Belirtilmemiş",
    "question": "“ İkişer tane H2A, H2B, H3 VE H4 ten oluşan bir histon çekirdek bölgesi etrafında 1.67 kez sarılmış, 147 DNA baz çiftini kapsar. “ Bu cümle aşağıdaki şıklardan hangisine ait bir tanımdır ?",
