    "open_answer": "",
    "explanation": "İnsan ve memelilerde fazla glukozun karaciğer ve kasta depolandığı ana homopolisakkarit **glikojendir**; yoğun alfa-1,6 dallanma noktaları sayesinde iyot reaktifi (Lugol) ile kırmızı-menekşe / kırmızımsı kahverengi bir renk reaksiyonu verir.",
    "note": "Cevap anahtarı tıbbi literatüre göre tamamlanmıştır.",
