    "question": "Çekirdek zarı ile ilgili aşağıdaki cümlelerden hangisi yanlıştır?",
    "options": [
      {
        "letter": "A",
        "text": "Çekirdeğin hem iç hem dış zarının dış yüzeyinde nükleer lamina bulunmaktadır."
      },
      {
        "letter": "B",
        "text": "Çekirdeğin sadece dış zarında ribozomlar bulunur ve GER zarı ile devamlıdır."
      },
      {
        "letter": "C",
        "text": "Çekirdek zarında makromolekül geçişi sadece çekirdek porlarında gerçekleşir."
      },
      {
        "letter": "D",
        "text": "Perinükleer aralık sisterna-GER lümeni ile devamlıdır."
      },
      {
        "letter": "E",
        "text": "9 nm çapına kadar olan küçük molekül ve iyonlar serbestçe porlardan geçerler."
      }
    ],
    "answer": "A",
    "open_answer": "",
    "explanation": "**Nükleer lamina**, lamin ara filamanlarından yapılmış fibröz bir ağ tabakası olup hem iç hem dış zarda değil, yalnızca **iç nükleer zarın nükleoplazmaya bakan iç yüzeyinde** yer alır ve çekirdeğe mekanik destek sağlar. Dış çekirdek zarı ise ribozomlar taşır ve GER ile devamlıdır.",
