    "professor": "Belirtilmemiş",
    "question": "Ara ara keloasidoza giren bir diyabet hastasının yüzündeki netrotik lezyondan örnek alınmış ve hazırlanan mikroskobik preparatta düzensiz dallanma gösteren, nadiren septalanması olan geniş hifler görülmüştür. Bu hasta için en olası tanı aşağıdakilerden hangisidir?",
