    "year": "2018-2019",
    "q_num": 131,
    "subject": "Mikrobiyoloji",
    "professor": "Hüseyin Haydar Kutlu",
    "question": "Pozitif polariteli tek iplikli RNA virüslerinin en önemli replikasyon özelliği aşağıdakilerden hangisidir?",
    "options": [
      {
        "letter": "A",
        "text": "Revers transkriptaz ile RNA'dan DNA sentezlemeleri"
      },
      {
        "letter": "B",
        "text": "Parental genomik RNA'yı doğrudan mRNA olarak kullanabilmeleri"
      },
      {
        "letter": "C",
        "text": "Replikasyonlarını mutlaka hücre çekirdeğinde gerçekleştirmeleri"
      },
      {
        "letter": "D",
        "text": "Sadece tomurcuklanma yoluyla konak hücreden ayrılmaları"
      },
      {
        "letter": "E",
        "text": "Virion içinde RNA bağımlı RNA polimeraz enzimi taşımaları"
      }
    ],
    "answer": "B",
    "open_answer": "",
    "explanation": "Pozitif polariteli tek iplikli (+)ssRNA virüslerinin genomik RNA'sı ökaryotik mRNA ile aynı yönelimdedir (şapkalı ve poli-A kuyruklu); bu sayede konak hücresine girdiklerinde genom doğrudan **mRNA olarak işlev görür** ve virionda polimeraz taşımaya gerek duymadan translasyona uğrar.",
    "note": "Hatırlanan 4 şıklı sorudan 5 şıklı çoktan seçmeli soruya tamamlanmıştır.",
