    "open_answer": "",
    "explanation": "Sitozolden nükleer lokalizasyon sinyali (NLS) taşıyan kargoyu nükleusa taşıyan importin reseptörü, nükleus içine girdiğinde yüksek konsantrasyondaki **Ran-GTP** ile bağlanır; bu bağlanma importinin kargosunu serbest bırakmasını sağlar ve import döngüsünü tamamlar.",
