    "professor": "Belirtilmemiş",
    "question": "Hücre döngüsünün düzenlenmesinde aşağıdakilerden hangisi gerçekleşmez?",
    "options": [
      {
        "letter": "A",
        "text": "Hücreler interfaz süresince sabit bir hızda büyür."
      },
      {
        "letter": "B",
        "text": "Sitokinezle Sonlanan mitozdan sonraki faz DNA sentezi ile mitoz arasındaki G1 fazıdır."
      },
      {
        "letter": "C",
        "text": "G1 fazının tamamlanmasıyla hemen G2 fazı başlar ve bu fazda hücre büyümeye devam eder."
      },
      {
        "letter": "D",
        "text": "Döngünün M evresi genellikle sitokinez ile devam eden mitozdur."
      },
      {
        "letter": "E",
        "text": "S kontrol noktasında hasarlı DNA ‘ nın onarılmadan kopyalanması engellenir. 72. ..................... sinyal iletiminde, hormonlar uzaktaki hedef hücrelerine dolaşım sistemi yoluyla taşınırlar. .................. sinyal iletiminde, bir hücreden salınan bir molekül komşu hedef hücreleri lokal olarak etkiler. ......................... sinyal iletiminde, bir hücre ürettiği sinyal iletimi molekülüne kendisi yanıt verir. Boşluklara sırayla aşağıdakilerden hangisi gelir."
      }
    ],
