    "question": "miRNA’ların etki mekanizmasında; I.Drosha ile işlenmesi, II.RNA polimeraz II tarafından primer transkriptin oluşması, III.RISC ile kompleksi ile birleşip hedef mRNA’nın baskılanması, IV. Sitoplazmada Dicer ile eşlenip plgun miRNA oluşması olaylarının gelişme sırası aşağıdakilerden hangisidir?",
