        "text": "Mitozon ilk evresinde kromozomlar yoğunlaşır ve hücrenin ortasına hareket ederler. B. Metefazda çok yoğunlaşmış kromozomlar kardeş kromatidler halinde ekvatora dizilirler. C. Anafazda kardeş kromatidler ayrılmadan zıt kutuplara hareket ederler. D. Telofaz aşamasında nükleer membranlar tekrar oluşur."
