    "question": "6 aylık bir bebek hastada hafif ateş rinit,kuvvetli öksürük belirtileri vardır.Nozoforenksten yapılan kültürde Bordetella perusis tespit edilmiştir.Bu toksin,solunum yollarının hücrelerindeki proteinlerinin normal çalışmasını önlemektedir. Bu enfeksiyona yanıt olarak solunum yolu sinyalindeki hücre aşağıdakilerden hangisidir?",
