    "question": "İki küçük düzenleyici RNA sınıfının (siRNA ve miRNA) kökeni ve/veya RNAi yolağı arasındaki ayrımı en iyi hangi ifade açıklamaktadır?",
    "options": [
      {
        "letter": "A",
        "text": "siRNAllar ağırlıklı olarak eksojen dsRNAldan kaynaklanır; miRNAllar hücre genomundan kaynaklanır."
      },
      {
        "letter": "B",
        "text": "miRNA ve siRNA aracılı gen susturma, hedef dsRNA üzerinde aynı susturma mekanizmalarını sağlayan evrimsel bağımsız yolları temsil eder.- Öğrencinin işaretlediği"
      },
      {
        "letter": "C",
        "text": "miRNA'Iar dsRNA virüslerinden işlenir, siRNA'lar ssRNA virüslerinden işlenir."
      },
      {
        "letter": "D",
        "text": "miRNAllar, siRNAlIar RNA dizilerini uygun şekilde bozamadığında ifade edilir."
      },
      {
        "letter": "E",
        "text": "miRNA aracılı gen susturma, siRNA aracılı susturmanın hedef dsRNAlyı susturmada başarısız olması durumunda bir yedek yolu temsil ederç"
      }
    ],
    "answer": "A",
    "open_answer": "",
    "explanation": "Gen susturma mekanizmasında **siRNA'lar** ağırlıklı olarak virüsler gibi eksojen çift zincirli RNA'lardan türetilirken; **miRNA'lar** konak hücresinin kendi nükleer genomundan transkribe edilen endojen kodlamayan RNA'lardır.",
