    "explanation": "**Transpozonlar (sıçrayan genler)**, hücre genomunda sabit kalmayan, 'kes-yapıştır' veya 'kopyala-yapıştır' mekanizmalarıyla genom içinde bir bölgeden başka bir bölgeye yer değiştirebilen hareketli (mobil) genetik elemanlardır; sabit ve değişmez oldukları iddiası yanlıştır.",
