    "explanation": "**Kolaylaştırılmış difüzyon**, elektrokimyasal gradyan yönünde gerçekleşen pasif bir taşımadır (ATP harcanmaz); ancak spesifik taşıyıcı proteinler (üniporterlar) aracılığıyla yürütüldüğü için enzim-substrat ilişkisine benzer şekilde **doygunluk (Vmax / saturasyon) kinetiği** sergiler.",
    "note": "Hatırlanan çıkmış soru kökünden 5 şıklı çoktan seçmeli soruya tamamlanmıştır.",
