    "explanation": "Uzun zincirli yağ asitlerine bağımlı lipofilik bir maya olan **Malassezia furfur**, rutin besiyerlerinde üremez; üremesi için besiyerine **zeytinyağı ilavesi** veya parenteral lipid infüzyonu gereklidir.",
