    "professor": "Hüseyin Haydar Kutlu",
    "question": "65 yaşında kadın hasta ağır bir üst solunum yolu enfeksiyonu sonrasında göğüs ve sırt bölgesinde tek taraflı dermatomda lokalize şiddetli ağrı ve veziküler döküntü şikayetiyle başvuruyor. Bu hastada en olası viral etken hangisidir?",
