    "professor": "Belirtilmemiş",
    "question": "Poxviridae ailesi için aşağıdaki ifadelerden hangileri doğrudur?\nI. Kompleks simetrili kapsid yapısına sahiptir\nII. Replikasyonu sitoplazmada gerçekleşir\nIII. Genomu tek iplikli RNA'dır",
