    "subject": "Mikrobiyoloji",
    "professor": "Rahşan Ilıkçı Sağkan",
    "question": "Üzerinde çalışılan hormonun normalde hücrenin çekirdeğinde bulunan hücre içi reseptörü vardır. Bu hormonun aşağıdakilerden hangisi olma olasılığı yüksektir?",
