    "professor": "Rahşan Ilıkçı Sağkan",
    "question": "Kolera toksini, solunum yollarının hücrelerindeki Gas altbirimini modifiye eder. GTP hidrolize edemez. Bu enfeksiyona yanıt olarak gastrointestinal sistemde hücre sinyalindeki bozulma aşağıdakilerden hangisidir?",
