    "open_answer": "",
    "explanation": "**Lig. iliolumbale**, crista iliaca ile 5. bel omurunun transvers çıkıntısı arasında uzanarak pelvisi stabilize eden bir bağdır; kalça ekleminin (art. coxae) kapsüler bağları arasında yer almaz.",
