    "subject": "Biyokimya",
    "professor": "Soycan Mızrak",
    "question": "20 aylık bir erkek bebek psikomotor gelişiminde gerikme ile hastaneye yatırılmıştır. Ayakta duramamakta ve yürüyememektedir. Yapılan kan analizinde yüksek düzeyde piruvat ve laktat saptanmıştır. Bir enzim yetmezliği olabileceğinden kuşkulanarak tiyamin başladığınız hastanın kliniğinde iyileşme saptanmış, 6 ay içinde yürümeye başlamıştır. Olası kuşkulandığınız enzim eksikliği aşağıdakilerden hangisidir?",
