    "professor": "Hüseyin Haydar Kutlu",
    "question": "El ayasındaki siyah renkli lezyon nedeniyle dermatolojiye başvuran hastada malign melanomdan şüphelenilerek biyopsi örneği alınmış fakat patoloji sonucuna göre malignite düşünülmemiştir. Alınan deri kazıntı örneğinin %10-20'lik potasyum hidroksit ile muamelesi sonrası mikroskopide mantar hifleri görülmüştür. Tablodan sorumlu olan en olası etken aşağıdakilerden hangisidir?",
