    "explanation": "Avuç içi veya ayak tabanında melanom benzeri asemptomatik hiperpigmente siyah maküllere (Tinea nigra) yol açan, deri kazıntısında demiyaseöz hifler oluşturan mantar etkeni **Hortaea werneckii**'dir.",
