    "question": "I. RNA polimeraz II, bir genin ilk eksonunun ilk nükleotidinde transkripsiyonu başlattıktan sonra , sentezlenmekte olan RNA’nın 5’ ucuna 7-metilguanilat şapkası eklenir. II. RNA polimeraz II tarafından transkripsiyon, son eksonun 3’ucunda yerleşen poli A bölgesinden aşağıda birçok sonlanma bölgesinin herhangi birinde sonlanır. Sonra birincil transkript poli A bölgesinde kesilir. III.  İntronlar RNA’dan kesip çıkarılır. Ökaryotik mRNA'ların işlenmesinde takip edilen sıra aşağıdailerden hangisidir",
