    "question": "Genellikle birbiriyle ilişkili enzimleri kodlayan genler DNA üzerinde birlikte bulunur. Tek bir regülatör bölge tarafından kontrol edilir.  Tek bir mRNA şeklinde transkribe edilmesine rağmen birbirinden bağımsız bir şekilde translasyona uğrar. Aşağıdakilerden hangisinde yukarıdaki özelliklere en uygun tanım verilmiştir?",
