    "question": "Oluşan peptit bağının salınımını ve mRNAdan ribozomun ayrılması basamaklarını içermektedir. Yukarıda protein sentezi aşamalarını açıklayan bilgiler verilmektedir. Aşağıdaki şıklardan hangisinde en uygun eşleşme verilmiştir?",
