    "professor": "Belirtilmemiş",
    "question": "Ökaryotlarda intronlar ve eksonlar için aşağıdakilerden hangisi doğrudur?",
    "options": [
      {
        "letter": "A",
        "text": "Olgun mRNA transkripti, intronların ve eksonların bir karışımını içerir."
      },
      {
        "letter": "B",
        "text": "Ekzonlar, tipik olarak bir genin uzak uçlarında bulunan tekrar eden dizilerdir."
      },
      {
        "letter": "C",
        "text": "Pre-RNA transkripti hem intronik hem de eksonik bölgeleri içerir.-Doğru Seçenek"
      },
      {
        "letter": "D",
        "text": "Intronic bölgeleri tipik olarak transkripsiyon faktörlerini kodlar."
      },
      {
        "letter": "E",
        "text": "Olgun mRNA transkripti yalnızca intronları içerir, çünkü ekzonlar ayrılmıştır."
      }
    ],
    "answer": "C",
    "open_answer": "",
    "explanation": "Ökaryotlarda transkripsiyonla ilk sentezlenen birincil transkript olan **pre-mRNA**, genin hem protein kodlayan **eksonik** hem de kodlamayan **intronik** bölgelerinin tamamını kapsar.",
    "note": "",
