    "subject": "Anatomi",
    "professor": "Mahmut Çay",
    "question": "Humerus kırığı ile acil servise gelen bir hastada elin 4. ve 5. parmaklarında duyu kaybı ve ulnar sinir (nervus ulnaris) zedelenmesi tespit edilmiştir. Kırık humerus'un hangi anatomik çıkıntısında gerçekleşmiştir?",
    "options": [
      {
        "letter": "A",
        "text": "Capitulum humeri"
      },
      {
        "letter": "B",
        "text": "Epicondylus lateralis"
      },
      {
        "letter": "C",
        "text": "Tuberculum minus"
      },
      {
        "letter": "D",
        "text": "Tuberculum majus"
      },
      {
        "letter": "E",
        "text": "Epicondylus medialis"
      }
    ],
    "answer": "E",
