    "explanation": "**Nervus ulnaris**, humerus'un distal medialindeki **epicondylus medialis** çıkıntısının hemen arkasında yer alan sulcus nervi ulnaris içinden geçer; bu epikondilin kırıklarında doğrudan hasarlanır.",
    "note": "Hatırlanan çıkmış soru kökünden 5 şıklı çoktan seçmeli soruya tamamlanmıştır.",
