    "open_answer": "",
    "explanation": "Triptofan metabolizmasında kinüreninaz enzimi kofaktör olarak piridoksal fosfat (B6 vitamini) kullanır; **B6 vitamini eksikliğinde** triptofan yıkılamaz ve idrarla anormal şekilde **ksantürenik asit** atılır.",
