    "subject": "Mikrobiyoloji",
    "professor": "Hüseyin Haydar Kutlu",
    "question": "Kuru öksürük, ateş ve halsizlik şikayetleri ile başvuran bir hastanın balgam kültüründe Mycoplasma pneumoniae üremesi olmuştur. Hastanın tedavisinde aşağıdaki antibiyotiklerden hangisinin kullanımının tedavi başarısızlığı ile sonuçlanması en olasıdır?",
    "options": [
      {
        "letter": "A",
        "text": "Seftriakson"
      },
      {
        "letter": "B",
        "text": "Siprofloksasin"
      },
      {
        "letter": "C",
        "text": "Klaritromisin"
      },
      {
        "letter": "D",
        "text": "Doksisiklin"
      },
      {
        "letter": "E",
        "text": "Moksifloksasin"
      }
    ],
    "answer": "A",
    "open_answer": "",
    "explanation": "**Mycoplasma pneumoniae**, hücre duvarı (peptidoglikan) sentezlemeyen bir bakteri olduğu için etki mekanizması hücre duvarı sentez inhibisyonu olan beta-laktam grubu **seftriaksona doğal dirençlidir**; makrolid veya kinolonlar tercih edilir.",
    "note": "",
    "q_type": "mcq",
    "incomplete": false,
    "incomplete_reason": ""
