    "open_answer": "",
    "explanation": "Linezolid, klindamisin ve eritromisin bakteriyel ribozomun 50S alt birimine bağlanır; floroquinolon grubu olan **siprofloksasin** ise ribozomu değil DNA giraz ve topoizomeraz IV'ü inhibe eder, 50S mutasyonundan etkilenmez.",
