    "question": "Bir CRISPR lokusunda CRISPR  clustered regularly interspaced palindromic repeats (düzenli aralıklarla bölünmüş palindromik tekrar  kümeleri) ile birlikte bulunan gen lokusu aşağıdakilerden hangisidir?",
