    "year": "2023-2024 (Pratik)",
    "q_num": 13,
    "subject": "Tıbbi Genetik",
    "professor": "Aynur Karadağ",
    "question": "Aşağıdakilerden hangisinde bir PCR döngüsündeki adımlar doğru sıra ile verilmiştir?",
    "options": [
      {
        "letter": "A",
        "text": "Denaturation, extension, annealing."
      },
      {
        "letter": "B",
        "text": "Annealing, denaturation, extension."
      },
      {
        "letter": "C",
        "text": "Denaturation, annealing, extension. AB.AM İ N SEMA SARI"
      },
      {
        "letter": "D",
        "text": "Elongation, annealing, denaturation."
      },
      {
        "letter": "E",
        "text": "Elongation, annealing, denaturation. Denaturation, extension, annealing.  Annealing, elongation, denaturation."
      }
    ],
    "answer": "C",
    "open_answer": "",
    "explanation": "Standart bir polimeraz zincir reaksiyonu (PCR) döngüsündeki üç basamak kronolojik olarak: Çift zincirin açıldığı **Denaturation (Denatürasyon)**, primerlerin bağlandığı **Annealing (Bağlanma)** ve polimerazın zinciri uzattığı **Extension (Uzama)** aşamalarıdır.",
    "note": "Pratik Sınav Sorusu",
