    "year": "2023-2024 (Pratik)",
    "q_num": 14,
    "subject": "Tıbbi Genetik",
    "professor": "Aynur Karadağ",
    "question": "DNA izolasyonu için aşağıdakilerden hangisi doğru değildir?",
    "options": [
      {
        "letter": "A",
        "text": "Alkol DNA içerisindeki su moleküllerini çekerek DNA'nın görünür hale gelmesini sağlar."
      },
      {
        "letter": "B",
        "text": "SDS (Sodyum Dodesil Sülfat), iyonik bir deterjandır ve DNA'nın yapısını bozar.- Doğru Seçenek"
      },
      {
        "letter": "C",
        "text": "STE (Salin Tris Edta), kan hücreleri için hipoosmolar, şelatörlü çözücü tampon ortamı sağlar."
      },
      {
        "letter": "D",
        "text": "NaCl, pozitif yüktü Na+ iyonlar ile, proteinlere bağlanmış olan negatif yüklü SDS' a bağlanarak proteinlerin kütlesini artırır ve proteinlerin çökmesini sağlar."
      },
      {
        "letter": "E",
        "text": "EDTA, + 2 yüklü iyonları (bivalan katyonlar) bağlayan bir şelatördür ve Mg++ iyonlarını bağladığından DNA' nın DNaz tarafından parçalanmasını önler."
      }
    ],
    "answer": "B",
    "open_answer": "",
    "explanation": "**SDS (Sodyum Dodesil Sülfat)**, anyonik bir deterjandır; hücre ve çekirdek zarlarındaki lipidleri eritir ve hücresel proteinleri denatüre eder ancak DNA'nın kovalent nükleotid omurgasını parçalamaz.",
